CREATE TABLE IF NOT EXISTS executive_runtime_config (key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS executive_runs (id TEXT PRIMARY KEY,slot_key TEXT NOT NULL UNIQUE,started_at INTEGER NOT NULL,completed_at INTEGER,status TEXT NOT NULL,result_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS executive_agent_actions (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,target_id TEXT,agent_code TEXT NOT NULL,action_code TEXT NOT NULL,service_code TEXT NOT NULL DEFAULT '',city_id TEXT NOT NULL DEFAULT '',zone_id TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,decision_json TEXT NOT NULL,evidence_json TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_executive_actions_target ON executive_agent_actions(target_id,created_at DESC);
CREATE TABLE IF NOT EXISTS executive_sales_directives (target_id TEXT PRIMARY KEY,mode TEXT NOT NULL,pressure_multiplier REAL NOT NULL DEFAULT 1,reason TEXT NOT NULL,authorized_discount_bps INTEGER NOT NULL DEFAULT 0,authorized_upgrade_codes_json TEXT NOT NULL DEFAULT '[]',margin_validation_required INTEGER NOT NULL DEFAULT 1,expires_at INTEGER NOT NULL,run_id TEXT NOT NULL,updated_at INTEGER NOT NULL);
